        if ((k == 0) || (a[i] > e[(k - 1)])) {
            d[k] = a[i];
            e[k] = b[i];
            k = (k + 1);
        } else {
            e[(k - 1)] = mx(e[(k - 1)], b[i]);
        }
    }
    emit(k);
    for (i = 0; i < k; i += 1) {
        emit(d[i]);
        emit(e[i]);
    }
    return 0;
}

